 // Exercise valid backup and rejection through the actual file input handler.
 await evaluate('document.getElementById("pause").click()');
 assert.equal(await evaluate(`(async()=>{const before=JSON.stringify(state);await importData({target:{files:[new File(['{"version":1}'],'bad.json')],value:'bad'}});return JSON.stringify(state)===before&&document.getElementById('import-preview').textContent.includes('无法导入');})()`),true);
 assert.equal(await evaluate(`(async()=>{const copy=JSON.parse(JSON.stringify(state));copy.history[0].note='<img src=x onerror=alert(1)>';await importData({target:{files:[new File([JSON.stringify(copy)],'backup.json')],value:'backup'}});document.getElementById('confirm-import').click();return state.history[0].note==='<img src=x onerror=alert(1)>'&&!document.querySelector('#app img');})()`),true);
 await send('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
 assert.equal(await evaluate('document.documentElement.scrollWidth<=window.innerWidth'),true);
 // Keyboard navigation reaches an operable control after programmatic heading focus.
 await send('Input.dispatchKeyEvent',{type:'keyDown',key:'Tab',code:'Tab',windowsVirtualKeyCode:9});
 await send('Input.dispatchKeyEvent',{type:'keyUp',key:'Tab',code:'Tab',windowsVirtualKeyCode:9});
 assert.equal(await evaluate('document.activeElement.tagName'), 'INPUT');
 await evaluate('document.getElementById("notice").textContent=""');
 await evaluate('document.getElementById("start").click()');
 assert.equal(await evaluate('document.activeElement.tagName'),'H1');
 assert.equal(await evaluate('document.documentElement.scrollWidth<=window.innerWidth'),true);
 const shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true});
 fs.writeFileSync(path.join(__dirname,'verification-mobile.png'),Buffer.from(shot.data,'base64'));
 await send('Emulation.setDeviceMetricsOverride',{width:1280,height:900,deviceScaleFactor:1,mobile:false});
 await evaluate('document.getElementById("pause").click()');
 await evaluate('document.getElementById("export").click()');
 for(let i=0;i<30;i++){if(fs.existsSync(path.join(__dirname,'.verification-downloads'))&&fs.readdirSync(path.join(__dirname,'.verification-downloads')).some(n=>n.endsWith('.json')))break;await new Promise(r=>setTimeout(r,100));}
 const downloaded=fs.readdirSync(path.join(__dirname,'.verification-downloads')).find(n=>n.endsWith('.json'));
 assert.ok(downloaded,'Actual backup download should exist');
 assert.equal(JSON.parse(fs.readFileSync(path.join(__dirname,'.verification-downloads',downloaded),'utf8')).history.length,3);
 await evaluate('document.getElementById("notice").textContent=""');
 const wide=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true});
 fs.writeFileSync(path.join(__dirname,'verification-desktop.png'),Buffer.from(wide.data,'base64'));
 // Quota/blocked storage path must preserve in-memory work and disclose the failure.
 assert.equal(await evaluate(`(()=>{const original=Storage.prototype.setItem;Storage.prototype.setItem=()=>{throw Error('quota')};persist();const result=!storageOK&&document.getElementById('notice').textContent.includes('未能保存');Storage.prototype.setItem=original;persist();return result&&storageOK;})()`),true);
})().then(()=>{console.log('Browser workflow checks passed');}).catch(err=>{console.error(err);process.exitCode=1;}).finally(async()=>{clearTimeout(timeout);try{await call('Browser.close');}catch{}child.kill();});
:root{color-scheme:light;--ink:#1e3534;--muted:#576b69;--green:#225e50;--line:#d5dfd9;--paper:#fffef9;--soft:#edf2e9;--amber:#765016}*{box-sizing:border-box}body{margin:0;background:#f4f3ec;color:var(--ink);font:16px/1.75 system-ui,"Microsoft YaHei",sans-serif}header,main,footer{max-width:1020px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;gap:16px;align-items:center;border-bottom:1px solid var(--line)}.brand{font-size:23px;font-weight:750;letter-spacing:.05em}.brand span{display:block;font-size:12px;font-weight:400;color:var(--muted)}.badge,.tag{font-size:12px;border:1px solid var(--line);border-radius:20px;padding:4px 12px;display:inline-block}main{min-height:65vh;padding-top:40px}h1{font-size:clamp(26px,4vw,38px);line-height:1.35;letter-spacing:-.02em;margin:10px 0 18px}h2{font-size:21px;margin:0 0 12px}h3{font-size:17px;margin:0 0 8px}p{margin:8px 0 16px}.eyebrow{color:var(--green);font-size:13px;letter-spacing:.12em}.muted,small{color:var(--muted)}.hero{display:grid;grid-template-columns:1.7fr 1fr;gap:28px;align-items:start}.card{background:var(--paper);padding:25px;border:1px solid var(--line);border-radius:14px;margin-bottom:20px}.soft{background:var(--soft)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.grid .card{padding:19px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0}button,.file-label{font:inherit;line-height:1.5;border:1px solid var(--green);background:var(--green);color:white;border-radius:8px;padding:11px 19px;cursor:pointer;display:inline-block;text-decoration:none}button.secondary,.file-label{background:transparent;color:var(--green)}button:disabled{opacity:.5;cursor:not-allowed}button:hover:not(:disabled),.file-label:hover{filter:brightness(.92)}:focus-visible{outline:3px solid #be7515;outline-offset:4px}fieldset{border:0;padding:0;margin:24px 0}legend{font-weight:700;margin-bottom:10px}.choice{display:flex;gap:10px;align-items:flex-start;border:1px solid var(--line);border-radius:9px;padding:13px 16px;margin:9px 0;cursor:pointer}.choice:has(input:checked){background:var(--soft);border-color:var(--green)}input[type=radio]{margin-top:7px;accent-color:var(--green);flex-shrink:0}textarea{display:block;width:100%;font:inherit;border:1px solid var(--line);border-radius:8px;padding:12px;background:white;margin-top:8px;min-height:84px}progress{width:100%;height:8px;accent-color:var(--green)}.topline{display:flex;justify-content:space-between;gap:12px;align-items:center}.scene{font-size:19px;line-height:1.9;border-left:3px solid #8b9f7a;padding-left:20px;margin:20px 0}.feedback{border-left:4px solid var(--green)}.feedback.retry{border-left-color:#ae7225}.feedback strong{font-size:20px}.source{font-size:14px;padding:15px;background:var(--soft);border-radius:8px}.stat{font-size:28px;font-weight:700;line-height:1.3}.warning{background:#fff1d5;color:#64491d;padding:12px 16px;border-radius:8px}.history{padding:12px 0;border-top:1px solid var(--line)}details{margin:18px 0}summary{cursor:pointer;font-weight:600}footer{font-size:12px;color:var(--muted);border-top:1px solid var(--line)}#notice:not(:empty){position:fixed;bottom:16px;left:50%;transform:translateX(-50%);background:var(--ink);color:white;padding:12px 24px;border-radius:9px;max-width:90vw;z-index:5}a{color:var(--green)}.hidden{display:none}ul{padding-left:22px}@media(max-width:650px){header,main,footer{padding:19px}.hero,.grid{grid-template-columns:1fr}.hero{gap:0}.card{padding:19px}header{align-items:flex-start}.badge{font-size:10px;padding:3px 8px;white-space:nowrap}.brand{font-size:20px}.topline{align-items:flex-start}.actions button{flex-grow:1}main{padding-top:26px}}
:where(h1, #feedback):focus{outline:none}

