"use strict";
// All scenarios are authored from inputs/规则.md; there is no remote service.
const RULES = {
 B1:{name:"预约 ≠ 实际借出",text:"预约只保留使用时段，不代表器材已经交到借用人手里。实际交接时核对器材编号、借用人和原有损伤，再记实际借出时间与双方确认。不能把预约时间直接填成实际交接时间。",gap:"是否有实际交接，以及编号、借用人、原有损伤和双方确认的证据"},
 B2:{name:"申请 ≠ 延期确认",text:"借用人提出延期只是申请。管理人明确确认前，原定归还时间不变；确认后记录新的归还时间及确认依据。不能仅因申请消息比旧记录新，就把申请当成已批准的新期限。",gap:"管理人是否明确确认，以及新期限和确认依据"},
 B3:{name:"放回 ≠ 验收完成",text:"把物品放回储物室不代表已经完成归还验收。管理人需按编号核对实物与交接时记录的状态。遇到状态差异，先记录差异和待核实事项，不自行认定损坏原因或责任人。检查确认后才标记归还完成。",gap:"是否已按编号和交接状态检查确认；差异原因是否仍待核实"}
};
// Each action and reason has its own key. Indices are shuffled deterministically per session.
const CASES = [
 {id:"b1a",rule:"B1",title:"预约成功以后",scene:"小周预约了明天 14:00 的投影仪 P03。系统显示预约成功，器材仍在柜里，尚未交接。现在如何记？",a:["保留预约，尚不能记为实际借出","把明天 14:00 填进实际借出时间","预约成功就标记已借出"],r:["预约只保留使用时段，没有实际交接","预约记录已经足以证明器材在小周手里","系统消息比人工交接更可靠"],explain:"这里只发生了预约。保留时段即可；实际借出要等核对和交接后再记录。",transfer:"如果后来交接了，应使用实际交接时间，而不是预约时间。"},
 {id:"b1b",rule:"B1",title:"迟到的交接",scene:"音箱 S02 预约 15:00 使用。借用人 15:25 才到，双方于 15:30 完成编号、借用人、原有损伤核对并确认交接。实际借出时间填什么？",a:["15:30，并保留双方确认","15:00，和预约保持一致","15:25，到场就等于完成交接"],r:["应按实际交接记录，而不是预约或到场时间","预约时间对所有记录都有优先权","到场后就无需核对状态"],explain:"材料明确交接完成于 15:30，实际借出时间应记 15:30，并保留确认。",transfer:"早到、迟到都不改变原则：预约时间不能替代实际交接时间。"},
 {id:"b1c",rule:"B1",title:"熟人来取",scene:"熟悉的同学说“还是上次那台，直接给我吧”。你们还没核对这次的编号和原有损伤，也没完成交接确认。下一步？",a:["核对编号、借用人、原有损伤，实际交接时记时间和双方确认","沿用上次记录并立即标已借出","有熟人保证就省略核对"],r:["每次实际交接都需要规定的核对和记录","上次正确意味着这次状态一定相同","认识借用人即可证明器材编号和状态"],explain:"熟悉对方不能补足这次交接的证据。规则要求的核对和确认仍需完成。",transfer:"换成新同学、熟悉同学或同一器材，交接要求不变。"},
 {id:"b1d",rule:"B1",title:"只剩预约记录",scene:"表格里只有相机 C07 的预约时间 10:00，没有交接记录。有人问器材是否已经借出。只凭这些材料怎样回答？",a:["无法确定实际是否借出，需核实交接，不能补写成已发生","确定已于 10:00 借出","确定器材从未离开柜子"],r:["预约不能证明交接；缺少记录也不能证明现实中从未交接","没有记录就能证明事件绝对没有发生","只要有时间就能当实际借出时间"],explain:"材料只支持“有预约”，不支持实际已借出，也不支持绝对未交接。要核实实际交接事实。",transfer:"没有交接证据时，保持未知，不用猜测补齐记录。"},
 {id:"b1e",rule:"B1",title:"提前领走",scene:"支架 T04 预约 16:00。双方 15:40 已核对编号、借用人和原有损伤，并确认完成实际交接。怎样记录？",a:["记实际借出 15:40 及双方确认","仍记 16:00，因为预约如此","等到 16:00 再把器材视为已交接"],r:["实际交接事实和时间已明确，预约不替代它","提前交接会让实际时间失去效力","预约时间就是唯一可记录的时间"],explain:"借出记录要反映 15:40 的实际交接。材料未提供其他提前领取政策，不能额外推断。",transfer:"判断依据是交接事实，不是时间早于还是晚于预约。"},
 {id:"b1f",rule:"B1",title:"少了一项核对",scene:"对方到场，你核对了器材编号和借用人，但还没核对原有损伤，也没完成双方确认。能直接完成这次借出登记吗？",a:["先补齐原有损伤核对，交接时记录实际时间与双方确认","已经核对两项，可以直接完成","把预约时间填进去即可"],r:["原有损伤核对和双方确认也是交接要求的一部分","只要对方到场就满足全部要求","损伤只在归还时需要关心"],explain:"不能用已完成的部分代替全部步骤。补齐状态核对，按实际交接记录时间和双方确认。",transfer:"归还时要对照交接状态，因此借出时记录原有损伤很关键。"},
 {id:"b2a",rule:"B2",title:"新消息来了",scene:"原定周五 18:00 归还。周五 16:00 借用人发来“想延到周日”，管理人尚未确认。现在截止时间怎么记？",a:["仍是周五 18:00，延期申请待确认","改成周日，消息比原记录新","删除原期限，等待下一条消息"],r:["管理人明确确认前，原定归还时间不变","较新的消息自动覆盖旧期限","借用人提出申请就已经完成延期"],explain:"新消息是申请，不是批准。原期限仍有效；可注明申请待确认。",transfer:"消息更晚不代表效力更高。关键是有无管理人的明确确认。"},
 {id:"b2b",rule:"B2",title:"确认已收到",scene:"原定周二归还。借用人申请延期到周四 17:00，管理人明确回复“同意，新的归还时间为周四 17:00”。下一步？",a:["更新为周四 17:00，并记录这次确认依据","永远保留周二，因为申请不能改变期限","只改时间，不留确认依据"],r:["管理人已明确确认，应记录新期限和确认依据","任何延期消息都只能作为申请","确认后只记新时间就足够"],explain:"这次既有申请，也有管理人明确确认，因此可以更新，但还需保留确认依据。",transfer:"不要把“申请不等于确认”误记成“任何时候都不能改”。"},
 {id:"b2c",rule:"B2",title:"消息显示已读",scene:"借用人提出延长一天。聊天显示管理人已读，但没有明确回复同意。怎样处理？",a:["原期限不变，继续核实是否获得明确确认","已读等于默许，直接延长一天","先改期限，等有异议再撤回"],r:["已读不是管理人明确确认延期的证据","只要对方看到消息就完成确认","未反对等同明确同意"],explain:"材料只有已读，没有明确确认；原期限不变。可补问确认，而不能把沉默解释成批准。",transfer:"未回复、已读、申请措辞很肯定，都不能替代明确确认。"},
 {id:"b2d",rule:"B2",title:"又申请了一次",scene:"管理人已明确同意把周一的归还期限改到周三 12:00，并已记录依据。随后借用人又申请改到周四，尚未获确认。当前有效期限？",a:["周三 12:00，第二次申请待确认","周四，因为它是最新的申请","周一，因为延期都不能生效"],r:["已确认的新期限有效，后续未确认申请不能覆盖它","最新申请一定覆盖所有确认","原始期限永远不能变更"],explain:"有效记录是已确认的周三 12:00。新的周四申请还没确认，不能覆盖它。",transfer:"对比两条消息时，区分它们是申请还是确认，不只比较先后。"},
 {id:"b2e",rule:"B2",title:"确认说法不清",scene:"借用人说“我应该可以多用一天吧”，又说“管理员大概会同意”。材料里没有管理人明确确认。能改期限吗？",a:["不能据此改，原期限不变，需核实明确确认","可以，借用人对结果很有把握","先按大概同意处理"],r:["借用人的推测不能充当管理人的明确确认","语气肯定就意味着已经获批","只要没有拒绝就可以改"],explain:"借用人的预计不是管理人的确认。不要在记录中把“可能会同意”变成“已经同意”。",transfer:"把说话者和证据类型分清，比判断语气更可靠。"},
 {id:"b2f",rule:"B2",title:"只改了一半",scene:"管理人明确确认新的归还时间为周六 10:00。你把表格改成该时间，却没有记录确认依据。还需要做什么？",a:["补记管理人的确认依据","不用补，时间正确就全部完成","恢复旧时间，任何确认都无效"],r:["确认后应同时记录新归还时间及确认依据","确认依据只是可有可无的备注","规则不允许更新任何期限"],explain:"延期已获确认，不应恢复旧时间；但记录还不完整，需要补充确认依据。",transfer:"判断能否延期和检查记录是否完整，是同一流程的不同检查点。"},
 {id:"b3a",rule:"B3",title:"物品已在柜里",scene:"借用人发消息“麦克风放回储物室了”。管理人还没有检查。现在如何标记？",a:["记录已报告放回、待验收，不标归还完成","已在储物室就标归还完成","直接认定器材完好"],r:["放回不等于按编号和交接状态检查确认","只要物品回到房间就满足验收","借用人的消息等同管理人的验收"],explain:"已报告放回只说明一项信息，不能代替检查。管理人需按编号和交接状态核对后再确认完成。",transfer:"位置变化不等于状态已核实。"},
 {id:"b3b",rule:"B3",title:"多了一道划痕",scene:"管理人按编号核对归还的相机，发现外壳划痕与交接记录不同。原因尚不清楚。下一步？",a:["记录状态差异和待核实事项，不自行判定原因或责任人","直接写借用人造成损坏","忽略差异并立即标归还完成"],r:["状态差异是已知事实，原因和责任仍待核实","发现差异就能证明是谁造成的","没有证据说明责任就不能记录差异"],explain:"可以记录划痕差异，但不能把差异直接解释成借用人造成。先留待核实，再完成检查确认流程。",transfer:"“发现什么”与“谁造成、为什么”是不同层次的证据。"},
 {id:"b3c",rule:"B3",title:"核对已经完成",scene:"管理人按编号核对音箱实物，并对照交接时的状态记录，检查确认无差异。现在能怎么记？",a:["可以标记归还完成","只能记放回，永远不能完成","必须先假定有人损坏过"],r:["已完成规则要求的编号、状态核对和检查确认","所有归还都要等待额外批准，规则才有效","即使已检查，也不能确认归还"],explain:"材料明确完成了检查确认，符合标记归还完成的条件。无需添加材料未给出的额外门槛。",transfer:"前置步骤确实完成后，就可以推进状态；不是一律停在待办。"},
 {id:"b3d",rule:"B3",title:"谁摔过它？",scene:"归还的支架比交接记录多了弯曲。借用人说“可能是运输时摔的”，没有其他证据。你应怎样记？",a:["记录弯曲差异及借用人的说法，原因和责任待核实","将运输摔坏记成确定原因","认定借用人故意损坏"],r:["一种可能解释不是已确认的损坏原因","借用人的猜测足以确定事故经过","发生弯曲就足以确定故意行为"],explain:"弯曲差异可以如实记；“可能摔过”只能作为待核实说法，不能记成确定原因或责任结论。",transfer:"保留说法的来源和不确定性，避免把解释写成事实。"},
 {id:"b3e",rule:"B3",title:"看起来是同一台",scene:"柜里放着外观相同的投影仪，管理员说看起来没问题，但还没有核对编号，也没对照交接状态记录。能标完成吗？",a:["先按编号和交接状态检查确认，再标完成","外观相同就能标完成","预约的是这台，所以柜里一定也是这台"],r:["外观印象不能代替编号和交接状态核对","同型号器材可共用所有交接记录","预约已自动证明归还器材的身份"],explain:"看起来相同不代表编号正确，也不能证明状态一致。仍需完成规定核对和检查确认。",transfer:"不只问“有没有检查”，还要问“检查了什么、对照什么”。"},
 {id:"b3f",rule:"B3",title:"交接时就有划痕",scene:"按编号核对后，发现相机有一道划痕；交接记录明确写着同位置同样的划痕。管理人已检查确认其他状态也一致。如何处理？",a:["按已完成检查确认，标记归还完成","只要有划痕就认定这次损坏","有划痕的器材永远不能归还"],r:["应对照交接时状态；材料表明没有新增差异且已检查确认","所有痕迹都必须归因于这次借用","归还标准是没有任何使用痕迹"],explain:"这道划痕是已记录的原有状态，不是本次新增差异。材料明确检查确认一致，可以完成归还。",transfer:"归还时比较的是交接状态，不能把原有损伤当成本次造成。"}
];
const KEY="jiehuan-practice-v1", VERSION=1;
const app=document.getElementById("app");
let state={version:VERSION,history:[],session:null},storageOK=true,view="home";
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const byId=id=>CASES.find(q=>q.id===id);
const dateLabel=t=>new Date(t).toLocaleString("zh-CN",{month:"numeric",day:"numeric",hour:"2-digit",minute:"2-digit"});
function validDraft(d){return d&&["a","r","confidence"].every(k=>d[k]===undefined||(Number.isInteger(d[k])&&d[k]>=0&&d[k]<(k==="confidence"?3:3)))&&(d.note===undefined||(typeof d.note==="string"&&d.note.length<=2000));}
function valid(s){
 if(!s||s.version!==VERSION||!Array.isArray(s.history)||s.history.length>50000)return false;
 if(!s.history.every(h=>h&&byId(h.id)&&Number.isFinite(h.at)&&Number.isInteger(h.a)&&h.a>=0&&h.a<3&&Number.isInteger(h.r)&&h.r>=0&&h.r<3&&Number.isInteger(h.confidence)&&h.confidence>=0&&h.confidence<3&&typeof h.note==="string"&&h.note.length<=2000))return false;
 if(s.session===null)return true;
 const x=s.session;
 return !!(x&&Array.isArray(x.ids)&&x.ids.length>=3&&x.ids.length<=6&&new Set(x.ids).size===x.ids.length&&x.ids.every(id=>byId(id))&&Number.isInteger(x.index)&&x.index>=0&&x.index<=x.ids.length&&Number.isFinite(x.started)&&Array.isArray(x.answers)&&x.answers.length===x.index+(x.submitted?1:0)&&x.answers.every((h,i)=>s.history.includes(h)||s.history.some(t=>JSON.stringify(t)===JSON.stringify(h)))&&x.answers.every((h,i)=>h.id===x.ids[i])&&typeof x.submitted==="boolean"&&(!x.submitted||x.index<x.ids.length)&&validDraft(x.draft));
}
let noticeTimer;
function notify(message){clearTimeout(noticeTimer);document.getElementById("notice").textContent=message;noticeTimer=setTimeout(()=>{document.getElementById("notice").textContent="";},6000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;notify("浏览器未能保存进度。请先导出记录备份，关闭后可能丢失。");}}
try{const raw=localStorage.getItem(KEY);if(raw){const saved=JSON.parse(raw);if(!valid(saved))throw Error("invalid");state=saved;}}catch(e){storageOK=false;notify("已有记录不可读或存储不可用。当前可练习；导出备份后再关闭。未覆盖原记录。");}
const correct=h=>h.a===0&&h.r===0;
function stats(rule){const hs=state.history.filter(h=>byId(h.id).rule===rule);const recent=hs.slice(-4);return {total:hs.length,right:hs.filter(correct).length,recent,distinct:new Set(hs.filter(correct).map(h=>h.id)).size,last:hs.length?hs[hs.length-1]:null};}
function status(rule){const s=stats(rule);if(!s.total)return "还未练习";if(s.recent.some(h=>!correct(h)))return "需要再辨析";if(s.distinct>=3&&s.recent.length>=3&&s.recent.every(correct))return "近期较稳 · 仍需复习";return "继续换情境检验";}
function orders(id,kind,seed){const n=Array.from(id+kind+seed).reduce((a,c)=>a+c.charCodeAt(0),0);const all=[[1,0,2],[2,1,0],[0,2,1],[2,0,1],[1,2,0],[0,1,2]];return all[n%6];}
function buildQueue(now=Date.now()){
 const rank=q=>{const hs=state.history.filter(h=>h.id===q.id),last=hs[hs.length-1];const s=stats(q.rule);if(!last)return (s.last&&!correct(s.last)?-120:-40)+s.total;return (!correct(last)?-100:last.confidence===0?-60:0)+Math.min(0,(last.at-now)/86400000);};
 const groups=Object.keys(RULES).sort((a,b)=>{const sa=stats(a),sb=stats(b);return (sa.last&& !correct(sa.last)?-10:0)+sa.total-((sb.last&&!correct(sb.last)?-10:0)+sb.total);});
 const lists=groups.map(r=>CASES.filter(q=>q.rule===r).sort((a,b)=>rank(a)-rank(b)));
 const ids=[];for(let turn=0;turn<2;turn++)for(const list of lists)ids.push(list[turn].id);return ids;
}
function start(){const first=state.history.length===0;state.session={ids:first?["b1a","b2a","b3a"]:buildQueue(),index:0,answers:[],draft:{},submitted:false,started:Date.now()};persist();view="practice";render();}
function ruleDetails(){return `<details><summary>查看规则原文与练习边界</summary><p class="muted">以下引文来自 inputs/规则.md；困惑材料仅用于确定练习重点，不作为规则。情境和练习安排为本页编写，不新增处罚、押金或审批政策。</p>${Object.entries(RULES).map(([id,r])=>`<h3>${id} · ${r.name}</h3><p>${r.text}</p>`).join("")}<a href="inputs/规则.md">打开原始规则材料</a></details>`;}
function storageWarning(){return storageOK?"":'<p class="warning">当前自动保存不可用或原记录不可读。离开前请导出本轮记录。</p>';}
function home(){const active=state.session&&state.session.index<state.session.ids.length;const count=state.history.length;
 app.innerHTML=`${storageWarning()}<div class="hero"><section><div class="eyebrow">每天约 10 分钟 / 从情境出发</div><h1>看懂规则之后，<br>练习下一步怎么做。</h1><p class="muted">先判断处理方式，再选理由。换一个说法、时间或状态，看看自己还能不能分清。</p><div class="actions"><button id="start">${active?"接着上次练习":count?"开始今天的一轮 · 6 题":"开始摸底 · 3 题"}</button></div><p class="muted">${active?`已保存到第 ${state.session.index+1} / ${state.session.ids.length} 题，已选答案和随手解释也会恢复。`:count?"优先安排上次答错、没把握和较久未练的情境；每轮覆盖三类规则。":"首次先定位三种常见混淆；之后每轮 6 题，约 8–12 分钟。"}</p></section><aside class="card soft"><h2>今天带着这个问题练</h2><p>“材料里明确发生了什么？<br>还缺哪一步，才能往下记？”</p><small>选对处理方式但理由不对，仍会进入复习。自己的解释供对照，不作自动语义评分。</small></aside></div><h2>我的薄弱点</h2><p class="muted">这是练习证据，不是合格认证。题目重复答对也不代表已会处理所有新情况。</p><div class="grid">${Object.entries(RULES).map(([id,r])=>{const s=stats(id);return `<section class="card"><span class="eyebrow">${id}</span><h3>${r.name}</h3><p>${status(id)}</p><div class="stat">${s.right}<span class="muted"> / ${s.total}</span></div><small>处理与依据均正确 / 已作答<br>正确覆盖 ${s.distinct} / 6 种情境</small>${s.last&&!correct(s.last)?`<p class="muted">下次重点：${r.gap}。</p>`:""}</section>`;}).join("")}</div><section class="card"><h2>最近练习</h2>${count?state.history.slice(-6).reverse().map(h=>`<div class="history"><span class="tag">${byId(h.id).rule}</span> ${esc(byId(h.id).title)} · ${correct(h)?"处理和依据均正确":"需再辨析"}<br><small>${dateLabel(h.at)} · 当时${["没把握","有些把握","很有把握"][h.confidence]}${h.note?` · 我的解释：${esc(h.note)}`:""}</small></div>`).join(""):"<p class='muted'>还没有记录。第一次摸底不是考试，用来找到练习起点。</p>"}</section>${ruleDetails()}<details><summary>备份与恢复学习记录</summary><p>同一浏览器、同一文件位置通常可接着练。清理浏览器数据、换浏览器或移动文件可能失去本地记录，请导出备份。导入会替换当前记录，先确认文件。</p><div class="actions"><button class="secondary" id="export">导出记录 JSON</button><label class="file-label" for="import">选择备份文件</label><input class="hidden" id="import" type="file" accept=".json,application/json"></div><div id="import-preview"></div></details>`;
 document.getElementById("start").onclick=()=>{if(active){view="practice";render();}else start();};
 document.getElementById("export").onclick=exportData;document.getElementById("import").onchange=importData;
}
function choices(q,kind,title){const x=state.session;return `<fieldset><legend>${title}</legend>${orders(q.id,kind,x.started).map(i=>`<label class="choice"><input type="radio" name="${kind}" value="${i}" ${x.draft[kind]===i?"checked":""} ${x.submitted?"disabled":""}><span>${q[kind][i]}</span></label>`).join("")}</fieldset>`;}
function practice(){const x=state.session;if(!x){view="home";home();return;}if(x.index>=x.ids.length){summary();return;}const q=byId(x.ids[x.index]);
 app.innerHTML=`${storageWarning()}<div class="topline"><span class="eyebrow">${x.ids.length===3?"首次摸底":"变式练习"} · 第 ${x.index+1} / ${x.ids.length} 题</span><button class="secondary" id="pause">保存并返回</button></div><progress value="${x.index}" max="${x.ids.length}" aria-label="本轮已完成题数"></progress><section class="card"><h1>${q.title}</h1><p class="scene">${q.scene}</p><form id="answer">${choices(q,"a","1. 你会怎样处理？")}${choices(q,"r","2. 最关键的依据是什么？")}<fieldset><legend>3. 这次有多大把握？</legend>${["没把握，主要靠猜","有些把握","很有把握，能说清区别"].map((t,i)=>`<label class="choice"><input type="radio" name="confidence" value="${i}" ${x.draft.confidence===i?"checked":""} ${x.submitted?"disabled":""}>${t}</label>`).join("")}</fieldset><label for="note">用自己的话说：材料明确了什么，还缺什么？<span class="muted">（可选，留给自己对照）</span></label><textarea id="note" maxlength="2000" ${x.submitted?"disabled":""} placeholder="先想一想，再看解析。不会也可以如实写下来。">${esc(x.draft.note||"")}</textarea>${x.submitted?"":'<p id="form-error" role="alert"></p><div class="actions"><button type="submit">提交并看反馈</button></div>'}</form></section><div id="feedback" tabindex="-1">${x.submitted?feedback(q,x.answers[x.answers.length-1]):""}</div>`;
 document.getElementById("pause").onclick=()=>{persist();view="home";render();};
 const form=document.getElementById("answer");
 form.onchange=e=>{if(x.submitted)return;if(["a","r","confidence"].includes(e.target.name)){x.draft[e.target.name]=Number(e.target.value);persist();}};
 document.getElementById("note").oninput=e=>{if(!x.submitted){x.draft.note=e.target.value;persist();}};
 form.onsubmit=e=>{e.preventDefault();if(x.submitted)return;if(!["a","r","confidence"].every(k=>Number.isInteger(x.draft[k]))){document.getElementById("form-error").textContent="请选好处理方式、依据和把握程度，再提交。";return;}const h={id:q.id,at:Date.now(),a:x.draft.a,r:x.draft.r,confidence:x.draft.confidence,note:x.draft.note||""};state.history.push(h);x.answers.push(h);x.submitted=true;persist();render(false);document.getElementById("feedback").focus();};
 if(x.submitted)document.getElementById("next").onclick=()=>{x.index++;x.submitted=false;x.draft={};persist();render();};
}
function feedback(q,h){const ok=correct(h);return `<section class="card feedback ${ok?"":"retry"}"><strong>${ok?"这次处理和依据都对了":h.a===0?"处理选对了，依据还需辨析":h.r===0?"依据选对了，处理步骤还需辨析":"这一步需要重新辨析"}</strong><p>${!ok&&h.confidence===2?"你刚才很有把握：把这里作为下一轮重点，检验是不是把两个状态当成了一个。":ok&&h.confidence===0?"这次答对但还没把握，之后会继续安排巩固。":"先对照证据，再看是否要改变自己的解释。"}</p><p><b>应如何处理：</b>${q.a[0]}<br><b>关键依据：</b>${q.r[0]}</p><p>${q.explain}</p><p class="source"><b>规则依据 · inputs/规则.md / ${q.rule}</b><br>${RULES[q.rule].text}</p><p><b>换个情况仍要看：</b>${q.transfer}</p>${h.note?`<p><b>回看我的解释：</b>${esc(h.note)}</p>`:""}<p class="muted">自己对照：我的解释有没有区分“已发生的事实”和“还缺的步骤”？本页只核对两项选择，不自动评判自由文字。</p><div class="actions"><button id="next">${state.session.index===state.session.ids.length-1?"看本轮回顾":"继续下一题"}</button></div></section>`;}
function summary(){const x=state.session,hs=x.answers,n=hs.filter(correct).length;app.innerHTML=`${storageWarning()}<div class="eyebrow">本轮已完成 · ${hs.length} 题</div><h1>${n===hs.length?"这轮分清了，再换情境巩固。":"知道卡在哪里，下次接着练。"}</h1><p>处理与依据均正确 <b>${n} / ${hs.length}</b>。${x.ids.length===3?"摸底结果只是起点，下一轮会增加不同情境。":"一轮到这里即可；明天可继续约十分钟。"}</p><section class="card"><h2>带走的三个检查点</h2>${Object.entries(RULES).map(([id,r])=>{const list=hs.filter(h=>byId(h.id).rule===id);return `<div class="history"><h3>${id} · ${r.name}</h3><p>${r.gap}。</p><small>本轮 ${list.filter(correct).length} / ${list.length} 题处理与依据均正确${list.some(h=>!correct(h)&&h.confidence===2)?" · 留意高把握错题":""}</small></div>`;}).join("")}</section><section class="card"><h2>本轮逐题回顾</h2>${hs.map(h=>`<details><summary>${esc(byId(h.id).title)} · ${correct(h)?"均正确":"需再辨析"}</summary><p>我的处理：${esc(byId(h.id).a[h.a])}<br>我的依据：${esc(byId(h.id).r[h.r])}</p><p>${byId(h.id).explain}</p><p class="source">${byId(h.id).rule}：${RULES[byId(h.id).rule].text}</p>${h.note?`<p>我的解释：${esc(h.note)}</p>`:""}</details>`).join("")}</section><div class="actions"><button id="home">回到学习页</button><button class="secondary" id="export">导出学习记录</button></div><p class="muted">${storageOK?"本轮已自动保存；重新打开后可开始下一轮。":"当前无法确认保存成功，请导出备份。"}</p>`;document.getElementById("home").onclick=()=>{view="home";render();};document.getElementById("export").onclick=exportData;}
function render(focus=true){if(view==="home")home();else practice();if(focus){const title=app.querySelector("h1");if(title){title.tabIndex=-1;title.focus();}window.scrollTo(0,0);}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`借还练习-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify("已发起导出，请保留下载的 JSON 文件。仅包含本机学习记录。");}
async function importData(e){const file=e.target.files[0],target=document.getElementById("import-preview");if(!file)return;try{if(file.size>10000000)throw Error();const incoming=JSON.parse(await file.text());if(!valid(incoming))throw Error();target.innerHTML=`<p class="warning">备份含 ${incoming.history.length} 次作答${incoming.session&&incoming.session.index<incoming.session.ids.length?"，含未完成练习":""}。确认后会替换当前 ${state.history.length} 次作答。建议先导出当前记录。</p><div class="actions"><button id="confirm-import">确认替换并恢复</button><button class="secondary" id="cancel-import">取消</button></div>`;document.getElementById("confirm-import").onclick=()=>{state=incoming;persist();view="home";render();notify(storageOK?"已恢复备份。":"已在当前页面恢复，请导出备份；自动保存不可用。");};document.getElementById("cancel-import").onclick=()=>{target.innerHTML="";e.target.value="";};}catch(err){target.textContent="无法导入：请选择本页导出的有效 JSON 备份（版本 1，10 MB 以内）。当前记录未改变。";e.target.value="";}}
render();

