// Optional offline check: node verify.cjs (uses an already installed Edge).
const {spawn}=require('node:child_process');
const fs=require('node:fs');
const path=require('node:path');
const assert=require('node:assert/strict');
const chrome='C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const profile=path.join(__dirname,'.browser-check');
const child=spawn(chrome,['--headless=new','--disable-gpu','--no-sandbox','--no-first-run','--no-default-browser-check','--disable-background-networking','--disable-component-update','--disable-sync','--metrics-recording-only','--remote-debugging-pipe',`--user-data-dir=${profile}-edge`],{stdio:['ignore','ignore','pipe','pipe','pipe'],windowsHide:true});
let browserErrors='';child.stderr.on('data',c=>browserErrors+=c.toString());
let serial=0,pending=new Map(),buffer='';
child.stdio[4].on('data',chunk=>{buffer+=chunk.toString();let at;while((at=buffer.indexOf('\0'))>=0){let raw=buffer.slice(0,at);buffer=buffer.slice(at+1);if(!raw)continue;const msg=JSON.parse(raw);if(msg.id&&pending.has(msg.id)){const {resolve,reject}=pending.get(msg.id);pending.delete(msg.id);msg.error?reject(Error(JSON.stringify(msg.error))):resolve(msg.result);}}});
function call(method,params={},sessionId){return new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});child.stdio[3].write(JSON.stringify({id,method,params,...(sessionId?{sessionId}:{})})+'\0');});}
const timeout=setTimeout(()=>{console.error('Browser check timed out',browserErrors.slice(-2500));child.kill();process.exit(1);},20000);
(async()=>{
 const {targetId}=await call('Target.createTarget',{url:'about:blank'});
 const {sessionId}=await call('Target.attachToTarget',{targetId,flatten:true});
 const send=(m,p)=>call(m,p,sessionId);
 const evaluate=async expression=>{const out=await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(out.exceptionDetails)throw Error(JSON.stringify(out.exceptionDetails));return out.result.value;};
 await send('Page.enable');
 await call('Browser.setDownloadBehavior',{behavior:'allow',downloadPath:path.join(__dirname,'.verification-downloads')});
 await send('Page.navigate',{url:require('node:url').pathToFileURL(path.join(__dirname,'index.html')).href});
