'use strict';
const RULES={B1:{name:'预约 ≠ 实际借出',text:'预约只保留使用时段。实际交接时核对器材编号、借用人和原有损伤，再记实际借出时间与双方确认。不能把预约时间直接填成实际交接时间。'},B2:{name:'申请 ≠ 延期确认',text:'提出延期只是申请。管理人明确确认前，原定归还时间不变；确认后记录新的归还时间及确认依据。申请消息更新不代表已经批准。'},B3:{name:'放回 ≠ 验收完成',text:'放回储物室不代表完成归还验收。按编号核对实物与交接时状态；遇到差异先记录差异和待核实事项，不自行认定原因或责任。检查确认后才标记归还完成。'}};
const BANK=[
['b1a','B1','预约成功，但尚未见面','小林预约了 14:00 使用相机 C07。现在 14:10，他还没来取。你准备填写实际借出记录。该怎么处理？',['不能标记已经实际借出；预约只保留时段。','实际交接时核对编号、借用人、原有损伤。','交接后记实际时间和双方确认，不能填预约时间。'],'预约时间和实际交接时间一定相同吗？'],
['b1b','B1','迟到后的交接','灯架 L03 预约 09:00，双方在 09:25 才实际交接。编号、借用人、原有损伤已核对，双方已确认。借出时间填什么？还有什么需要留下？',['记实际借出时间 09:25，不能填 09:00。','记录核对的编号、借用人、原有损伤及双方确认。'],'记录应描述已经发生的哪一次事件？'],
['b1c','B1','熟人取器材','熟悉的社员预约了话筒 M02，拿起话筒说“我们很熟，不用再核对了”。你如何完成交接？',['熟悉和预约不能替代交接核对。','核对器材编号、借用人、原有损伤。','记实际借出时间与双方确认。'],'熟悉的人是否也需要同样的交接证据？'],
['b1d','B1','群里一句“取走了”','预约表写着 16:00。16:40 群里出现“取走了”，材料没有说明实际交接时间、核对情况或双方确认。你能直接按 16:00 填实际借出吗？',['不能把预约时间或消息时间当作确定的实际交接时间。','核实实际交接时间、编号、借用人、原有损伤及双方确认；缺项待核实，不能补写成已发生。'],'消息能证明哪些事，又缺哪些交接信息？'],
['b2a','B2','新消息不是批准','原定今天 18:00 归还。17:50 借用人发来“想延到明天中午”，管理人没有回复。现在截止时间应怎么记？',['仍为今天 18:00，不能直接改成明天中午。','只记录为延期申请；等管理人明确确认后，才记新期限和确认依据。'],'提出申请的人是否就是确认的人？'],
['b2b','B2','延期已经明确确认','原定周三 18:00 归还。管理人明确回复“同意延至周四 12:00”。你怎样更新记录？',['新归还时间更新为周四 12:00。','记录管理人的明确确认作为依据；这次有确认，不能仍只当作申请。'],'什么新增事实使截止时间可以改变？'],
['b2c','B2','又来一次延期申请','已确认延至周四 12:00，借用人后来又申请周五 12:00，尚无管理人确认。现在用哪个期限？',['仍用已经确认的周四 12:00。','周五 12:00 只是新申请；明确确认后才改时间并记录依据。'],'最新消息和最新已确认期限有什么区别？'],
['b2d','B2','模糊回复','原定 20:00 归还，借用人申请延期。管理人回复“我看一下”，未给出明确确认或新期限。现在怎么处理？',['原定 20:00 不变，“我看一下”不构成明确批准。','进一步核实是否确认及新期限；确认后记录新时间和依据，不自行补出期限。'],'材料是否已经给出明确的确认？'],
['b3a','B3','已经放回储物室','借用人说“投影仪 P01 放回储物室了”。管理人还没检查。可以标记归还完成吗？下一步做什么？',['不能标记归还完成，放回不等于验收。','管理人按编号核对实物与交接时状态，检查确认后才完成。'],'物品位置变化是否等于检查已完成？'],
['b3b','B3','发现新增裂纹','相机 C07 已放回。检查时发现外壳裂纹，交接记录没有这条裂纹。有人说“一定是这次借用人摔的”。你怎么记录和处理？',['记录实物与交接记录的状态差异及待核实事项。','不能自行认定摔坏原因或责任人。','按编号核对并完成检查确认后，才标归还完成；不能仅因放回就完成。'],'差异是事实，原因和责任也已经被证实了吗？'],
['b3c','B3','验收已经完成','管理人已按编号核对音箱 S04 实物，状态与交接记录一致，并已检查确认。此时是否可以标归还完成？',['可以标记归还完成，因为已经检查确认。','依据是编号和交接状态核对及检查确认，而不只是物品已放回。'],'这次比“放回”多了什么关键步骤？'],
['b3d','B3','放回的是另一台','登记借出的是相机 C07，储物室新放回的是 C08，尚未核实原因。有人建议“都是相机，直接完成”。你怎么处理？',['不能把 C08 当成 C07 的归还验收完成。','记录编号不一致及待核实事项，核对实物和交接状态，不自行认定原因或责任。','检查确认后才标相应器材归还完成。'],'验收针对的是同类物品还是具体编号？']
].map(([id,rule,title,prompt,criteria,hint])=>({id,rule,title,prompt,criteria,hint}));
const KEY='equipment-practice-v1';let persistent=true;let loadIssue=false;let state=fresh();
function fresh(){return {version:1,history:[],session:null};}
function valid(s){return s&&s.version===1&&Array.isArray(s.history)&&s.history.length<50000&&s.history.every(h=>h&&BANK.some(q=>q.id===h.id)&&Number.isFinite(h.time)&&typeof h.pass==='boolean'&&typeof h.assisted==='boolean'&&typeof h.answer==='string'&&Array.isArray(h.checks)&&h.checks.every(x=>typeof x==='boolean')&&Array.isArray(h.missed)&&h.missed.every(x=>typeof x==='string'))&&(s.session===null||(s.session&&Array.isArray(s.session.ids)&&s.session.ids.length===3&&new Set(s.session.ids).size===3&&s.session.ids.every(id=>BANK.some(q=>q.id===id))&&Number.isInteger(s.session.pos)&&s.session.pos>=0&&s.session.pos<=3&&typeof s.session.draft==='string'&&['write','review','done'].includes(s.session.phase)&&Array.isArray(s.session.checks)&&s.session.checks.every(x=>typeof x==='boolean')&&typeof s.session.assisted==='boolean'&&(s.session.pos===3?s.session.phase==='done':s.session.phase!=='done')&&(s.session.phase!=='review'||s.session.checks.length===BANK.find(q=>q.id===s.session.ids[s.session.pos]).criteria.length)));}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!valid(parsed))throw Error('invalid');state=parsed;}}catch(e){persistent=false;loadIssue=true;}
const app=document.getElementById('app');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{if(loadIssue){const old=localStorage.getItem(KEY);if(old&&!localStorage.getItem(KEY+'-unreadable'))localStorage.setItem(KEY+'-unreadable',old);}localStorage.setItem(KEY,JSON.stringify(state));persistent=true;}catch(e){persistent=false;}document.getElementById('storage').textContent=persistent?(loadIssue?'⚠ 原记录无法读取，已在本机保留原文副本；当前从新进度开始，请导入可用备份恢复。':'● 进度自动保存在此浏览器 · 无需联网'):'⚠ 本机存储不可用或旧记录无法读取；当前进度请导出备份。';}
function last(id){return state.history.filter(h=>h.id===id).at(-1);}
function status(rule){const h=state.history.filter(h=>BANK.find(q=>q.id===h.id).rule===rule);if(!h.length)return '尚未练习';const recent=h.slice(-3),weak=recent.filter(x=>!x.pass||x.assisted).length;return weak?`近 ${recent.length} 次有 ${weak} 次需复练`:'近期自评完整 · 待间隔验证';}
function select(now=Date.now()){return Object.keys(RULES).map(rule=>BANK.filter(q=>q.rule===rule).sort((a,b)=>priority(b,now)-priority(a,now)||a.id.localeCompare(b.id))[0].id);}
function priority(q,now){const h=last(q.id);if(!h)return 50;const days=(now-h.time)/86400000;return (!h.pass||h.assisted?80:0)+Math.min(days,30)*8;}
function start(){state.session={ids:select(),pos:0,draft:'',phase:'write',checks:[],assisted:false};save();render();}
function render(){save();const s=state.session;if(!s){home();return;}if(s.pos===3){summary();return;}const q=BANK.find(x=>x.id===s.ids[s.pos]);app.innerHTML=`<div class="row"><span class="tag">本轮 ${s.pos+1} / 3</span><span class="muted">先独立处理，再查看核对标准</span><button id="home">暂存并回首页</button></div><progress value="${s.pos}" max="3" aria-label="本轮进度"></progress><section class="card"><span class="eyebrow">合成情境</span><h2>${q.title}</h2><p>${q.prompt}</p><label for="answer"><strong>你会怎么处理？为什么？还有什么不能确定？</strong></label><textarea id="answer" placeholder="先凭记忆写出判断、依据和下一步……" ${s.phase!=='write'?'readonly':''}>${esc(s.draft)}</textarea><p class="muted">文字不会自动判分。核对时请按你实际写出的内容判断。</p>${s.phase==='write'?`<div class="row"><button class="primary" id="reveal" ${!s.draft.trim()?'disabled':''}>写好了，核对思路</button><button id="hint">需要提示</button></div><div id="hintbox">${s.assisted?`<p class="notice">${q.hint} 本次计为有提示练习。</p>`:''}</div>`:reviewHTML(q,s)}</section>`;
document.getElementById('home').onclick=()=>home();document.getElementById('answer').oninput=e=>{s.draft=e.target.value;save();document.getElementById('reveal').disabled=!s.draft.trim();};if(s.phase==='write'){document.getElementById('hint').onclick=()=>{s.assisted=true;save();document.getElementById('hintbox').innerHTML=`<p class="notice">${q.hint} 本次计为有提示练习。</p>`;};document.getElementById('reveal').onclick=()=>{if(!s.draft.trim())return;s.phase='review';s.checks=q.criteria.map(()=>false);save();render();};}else{q.criteria.forEach((_,i)=>document.getElementById('c'+i).onchange=e=>{s.checks[i]=e.target.checked;save();});document.getElementById('finish').onclick=finish;} }
function reviewHTML(q,s){return `<h3>逐项核对你的原始回答</h3><p>只有原回答已经表达了这一点才勾选；看完才想起的内容留空。不同措辞也可以。空项会成为下次的复习重点。</p>${q.criteria.map((c,i)=>`<label class="check"><input id="c${i}" type="checkbox" ${s.checks[i]?'checked':''}>${c}</label>`).join('')}<p class="source"><strong>依据：规则.md · ${q.rule} ${RULES[q.rule].name}</strong><br>${RULES[q.rule].text}</p><p>这些核对点是依据规则编写的参考处理，不代表材料中未写出的事已经发生。</p><button class="primary" id="finish">保存本次核对</button>`;}
function finish(){const s=state.session;if(!s||s.phase!=='review')return;const q=BANK.find(x=>x.id===s.ids[s.pos]);state.history.push({id:q.id,time:Date.now(),answer:s.draft,checks:s.checks.slice(),missed:q.criteria.filter((_,i)=>!s.checks[i]),pass:s.checks.length===q.criteria.length&&s.checks.every(Boolean),assisted:s.assisted});s.pos++;s.draft='';s.checks=[];s.assisted=false;s.phase=s.pos===3?'done':'write';save();render();}
function summary(){const h=state.history.slice(-3);app.innerHTML=`<section class="card"><span class="eyebrow">今天的一小步，已保存</span><h2>这轮练习完成了</h2><p>独立且自评完整：${h.filter(x=>x.pass&&!x.assisted).length} / 3。自评完整不等于已经掌握，下次会换情境再验证。</p>${h.map(x=>`<h3>${BANK.find(q=>q.id===x.id).title}</h3><p>${x.pass?(x.assisted?'内容完整，但使用过提示；仍安排复练。':'本次独立自评完整。'):'还需复练：'+esc((x.missed||[]).join('；'))}</p>`).join('')}<button class="primary" id="end">回到学习首页</button></section>`;document.getElementById('end').onclick=()=>{state.session=null;save();home();};}
