document.getElementById('start').onclick=()=>state.session?render():start();document.getElementById('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='器材练习进度-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};document.getElementById('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error();const data=JSON.parse(await f.text());if(!valid(data))throw Error();if(!confirm('导入将替换当前进度。建议先导出当前备份。继续吗？'))return;state=data;save();home();document.getElementById('message').textContent='备份已恢复，可继续练习。';}catch(err){document.getElementById('message').textContent='未导入：文件不是受支持的完整进度备份，或文件过大。原进度保留。';}e.target.value='';};}
