/* Content adapted from inputs/课件.md W1–W3; practice and scheduling are local design choices. */
const topics=[
{id:'W1',name:'网址 ≠ 运行地点',source:'课件.md · W1',doubt:'我知道 localhost 这个单词，但还是不清楚为什么别人打不开。',prompt:'你的留言板在自己电脑上能用。朋友打开你发的 localhost 链接却失败了。请解释：朋友的浏览器在找哪台设备？买一个域名是否就能解决？还缺什么？',options:['买域名就会自动运行后端，朋友就能访问。','localhost 指向打开链接的设备；还需要朋友能访问的运行环境，域名只是名字。','朋友多刷新几次就会连接到我的电脑。'],correct:1,why:'localhost / 127.0.0.1 指向访问者自己的设备。域名帮助找到服务，但不会替你运行后端；朋友还需要能到达正在运行的服务。',rubric:['说明 localhost 指向打开链接的设备自身','区分域名这个名字与运行程序的计算机','说明需要朋友可达、实际运行服务的环境'],transfer:'换个情境：你关掉了运行网站的电脑，但域名还在。网站还能仅靠域名继续工作吗？',transferOptions:['能，域名会保存并运行整个网站。','不能仅靠域名；还要有实际运行且可达的服务。'],transferCorrect:1,explain:'域名不是运行环境。需要确认程序实际在哪里运行，以及它是否仍然可达。'},
{id:'W2',name:'本机保存 ≠ 大家共享',source:'课件.md · W2',doubt:'我以为“刷新还有”就说明数据保存好了，不知道跟朋友一起用有什么区别。',prompt:'你写了一条留言，刷新后还在。请向朋友解释：这证明了什么，又没有证明什么？要怎么检查“大家都看得到，而且服务重启也不丢”？',options:['刷新后还在就能证明所有人都看得到。','只要两个浏览器都用了 localStorage 就会同步。','这只证明当前浏览器保留了数据；要验证共同状态来源、独立客户端与服务重启后的结果。'],correct:2,why:'localStorage 通常属于当前来源下的浏览器本地数据。共享留言需要服务端等共同状态来源；独立客户端能看到、服务重启后仍保留，都需要分别检查。',rubric:['把刷新后还在限定为当前浏览器保留数据','说明不同浏览器的 localStorage 不会自动同步，需要共同状态来源','提出独立客户端读取和服务重启后保留两项检查'],transfer:'换个情境：朋友已在另一个浏览器看到了留言，但服务重启后留言消失。这能证明可靠保存了吗？',transferOptions:['不能；共享读取与重启后保留是两项不同检查。','能；朋友看到过就代表永久保存。'],transferCorrect:0,explain:'跨客户端读到内容验证了共享读取；服务重启后丢失说明保留性仍未满足。'},
{id:'W3',name:'界面隐藏 ≠ 权限验证',source:'课件.md · W3',doubt:'我以前以为把管理员按钮隐藏就可以了，不知道还要验证什么。',prompt:'报名页面只显示“我的报名”，却能通过改请求参数读取别人的记录。为什么隐藏按钮没解决问题？服务端该检查什么，应该怎样验证成员与管理员的行为？',options:['每次请求都检查身份与数据归属，拒绝成员越权，同时验证管理员正常访问。','把按钮颜色改淡，别人就不会点。','把管理员凭据放进页面，让页面自己决定谁能读取。'],correct:0,why:'界面不能限制直接请求。服务端必须逐次检查身份、数据归属；成员读取别人记录或全部名单应被拒绝，管理员正常查看应保留。可用管理员凭据不能放入公共页面。',rubric:['说明隐藏按钮挡不住直接请求','说明服务端对每次请求验证身份与数据归属','提出成员读取别人记录、全部名单被拒绝，以及管理员正常访问的检查','说明不能把可用管理员凭据放进公共页面'],transfer:'换个情境：成员不能读取别人记录了，但管理员也被一律拒绝。这个权限功能是否完成？',transferOptions:['完成了，拒绝所有人最省事。','没有；还必须保留管理员被授权的正常查看，并避免公共页面暴露凭据。'],transferCorrect:1,explain:'既要拒绝越权，也要保留授权访问。只验证拒绝路径不能证明权限功能完整。'}
];
const KEY='slow-understand-v1';
const day=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
function plus(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return day(d)}
function schedule(old,ok,date){const streak=ok?(old?.streak||0)+1:0;return {streak,due:plus(date,ok?[1,3,7,14][Math.min(streak-1,3)]:1),last:date,weak:!ok}}
function fresh(){return {version:1,records:{},history:[],session:null}}
function valid(s){return s&&s.version===1&&s.records&&typeof s.records==='object'&&!Array.isArray(s.records)&&Object.entries(s.records).every(([k,r])=>topics.some(t=>t.id===k)&&r&&Number.isInteger(r.streak)&&r.streak>=0&&/^\d{4}-\d{2}-\d{2}$/.test(r.due)&&typeof r.weak==='boolean')&&Array.isArray(s.history)&&s.history.every(h=>h&&topics.some(t=>t.id===h.id)&&typeof h.answer==='string'&&typeof h.ok==='boolean'&&typeof h.date==='string')&&(s.session===null||(s.session&&Array.isArray(s.session.ids)&&s.session.ids.length>0&&s.session.ids.every(id=>topics.some(t=>t.id===id))&&Number.isInteger(s.session.i)&&s.session.i>=0&&s.session.i<s.session.ids.length&&s.session.drafts&&typeof s.session.drafts==='object'&&Object.values(s.session.drafts).every(d=>d&&typeof d.answer==='string'&&typeof d.revealed==='boolean'&&Array.isArray(d.checks)&&d.checks.every(c=>typeof c==='boolean')&&(d.choice===null||Number.isInteger(d.choice))&&(d.transfer===null||Number.isInteger(d.transfer)))))}
if(typeof module!=='undefined')module.exports={topics,day,plus,schedule,valid,fresh};
if(typeof document!=='undefined'){
let state=fresh(),storageOK=true,loadError=false;
try{const raw=localStorage.getItem(KEY);if(raw){const s=JSON.parse(raw);if(!valid(s))throw Error();state=s}}catch(e){loadError=true;storageOK=false}
const app=document.getElementById('app'),notice=document.getElementById('notice');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{if(loadError)throw Error();localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;notice.textContent='已自动保存在本浏览器';}catch(e){storageOK=false;notice.textContent=loadError?'原有记录无法读取，未覆盖。可先导出原始记录，再清空损坏记录或导入有效备份。':'浏览器保存不可用。请在关闭前导出备份，否则进度会丢失。';notice.className='error'}}
function due(){return topics.filter(t=>!state.records[t.id]||state.records[t.id].due<=day()).sort((a,b)=>Number(state.records[b.id]?.weak||false)-Number(state.records[a.id]?.weak||false))}
function home(){const pending=due();app.innerHTML=`<section class="intro"><div class="tag">每天一点 · 把“看懂”变成“说得清”</div><h1>今天，弄懂一个为什么。</h1><p class="muted">合上课件先解释，再用新情境检查。不会的地方会留下来，明天接着练。</p></section><div class="grid"><section><div class="card hero"><span class="pill">今日复习</span><h2>${state.session?'你有一轮还没完成':pending.length?`${pending.length} 个主题等待回忆`:'今天的到期主题已完成'}</h2><p>${state.session?'回答和检查步骤已保留，可以从刚才的位置继续。':pending.length?'每个主题约 4 分钟。先凭记忆回答，再查看解释。':'明天再凭记忆解释，比马上重读更能发现遗忘。也可以现在加练。'}</p><button class="primary" id="start">${state.session?'继续复习':pending.length?'开始今日复习':'加练全部主题'}</button></div><div class="card"><h2>理解地图</h2>${topics.map(t=>{const r=state.records[t.id];return `<div><div class="row"><h3>${t.id} · ${t.name}</h3><span class="pill">${!r?'尚未检查':r.weak?'需要再练':'本次检查通过'}</span></div><p class="muted">${r?`下次：${r.due} · 连续通过 ${r.streak} 次`:'学习前疑问：'+esc(t.doubt)}</p></div>`}).join('')}<small>“通过”依据情境题和你的要点自查，不代表工具自动判定自由回答正确。通过后间隔依次为 1、3、7、14 天；未通过次日再练。</small></div></section><aside><div class="card"><h3>这 12 分钟怎么用</h3><p>① 用自己的话解释<br>② 做判断，再对照要点<br>③ 换个情境检验<br>④ 留下疑问，安排下次</p><small>先回忆后看答案；漏了哪一点，就只补那一点。</small></div><div class="card"><h3>记录与备份</h3><p class="muted">记录在本机当前浏览器。清除浏览器数据或移动文件可能影响保存。</p><button id="export">导出学习记录</button><label class="file">导入备份<input type="file" id="import" accept=".json,application/json" hidden></label><p id="import-status" role="status"></p>${loadError?'<button id="raw">导出原始记录</button><button id="reset">清空损坏记录</button>':''}</div></aside></div><div class="card"><h2>复习足迹</h2>${state.history.length?state.history.slice(-12).reverse().map(h=>`<details><summary>${esc(h.date)} · ${esc(h.id)} · ${h.ok?'本次通过':'需要再练'}</summary><p>当时的回答：${esc(h.answer)}</p><p>带走的疑问：${esc(h.note||'无')}</p></details>`).join(''):'<p class="muted">还没有完成记录。第一次练习后，这里会留下你的回答与疑问。</p>'}</div><details><summary>材料与练习的关系</summary><p>解释与检查要点来自 <a href="inputs/课件.md">课件 W1–W3</a>；起始疑问来自 <a href="inputs/我的疑问.md">我的疑问</a>。<a href="inputs/课程说明.md">课程说明</a>明确这些都是合成演示。题目、练习顺序、复习间隔由本工具设计，并非课件原文。没有外部 AI，自由回答允许不同正确措辞，请根据含义自查。</p></details>`;
document.getElementById('start').onclick=()=>{if(!state.session){state.session={ids:(pending.length?pending:topics).map(t=>t.id),i:0,drafts:{}};save()}exercise()};document.getElementById('export').onclick=()=>download(JSON.stringify(state,null,2),'复习记录-'+day()+'.json');document.getElementById('import').onchange=importFile;if(loadError){document.getElementById('raw').onclick=()=>download(localStorage.getItem(KEY)||'','原始记录.txt');document.getElementById('reset').onclick=()=>{if(confirm('确认清空无法读取的浏览器记录？请先导出原始记录。')){loadError=false;state=fresh();save();home()}}}}
function draft(){const s=state.session,t=topics.find(t=>t.id===s.ids[s.i]);return s.drafts[t.id]||(s.drafts[t.id]={answer:'',choice:null,revealed:false,checks:[],transfer:null,note:''})}
function exercise(){const s=state.session,t=topics.find(t=>t.id===s.ids[s.i]),d=draft();app.innerHTML=`<div class="row"><button id="home">← 返回首页</button><span>主题 ${s.i+1} / ${s.ids.length} · 约 4 分钟</span></div><progress value="${s.i}" max="${s.ids.length}"></progress><div class="card"><div class="tag">${t.id} · ${t.name}</div><h1>${d.revealed?'对照含义，检查漏洞':'先解释，再揭晓'}</h1><p>${t.prompt}</p><label for="answer">我的解释（不要求术语，先写你现在的理解）</label><textarea id="answer" placeholder="例如：我认为……因为……还需要检查……" ${d.revealed?'readonly':''}>${esc(d.answer)}</textarea><fieldset ${d.revealed?'disabled':''}><legend>选择最合理的解释</legend>${t.options.map((o,i)=>`<label class="option"><input type="radio" name="choice" value="${i}" ${d.choice===i?'checked':''}>${o}</label>`).join('')}</fieldset>${!d.revealed?'<button class="primary" id="reveal">提交并查看检查要点</button><p id="validation" role="alert"></p>':`<div class="feedback"><strong>${d.choice===t.correct?'情境判断正确':'这个判断需要修正'}</strong><p>${t.why}</p><small>依据：inputs/${t.source}</small></div><h2>我的原回答包含哪些意思？</h2><p class="muted">只勾选原回答已经讲清楚的要点。刚看了答案才明白的先不勾，明天再练。这里不按关键词评分。</p>${t.rubric.map((r,i)=>`<label class="option"><input type="checkbox" data-check="${i}" ${d.checks[i]?'checked':''}>${r}</label>`).join('')}<fieldset><legend>${t.transfer}</legend>${t.transferOptions.map((o,i)=>`<label class="option"><input type="radio" name="transfer" value="${i}" ${d.transfer===i?'checked':''}>${o}</label>`).join('')}</fieldset><label for="note">还有哪里不明白？或者下次要记住什么？（可选）</label><textarea id="note" style="min-height:85px">${esc(d.note)}</textarea><button class="primary" id="finish">完成检查，安排下次</button><p id="validation" role="alert"></p>`}</div>`;
document.getElementById('home').onclick=home;document.getElementById('answer').oninput=e=>{d.answer=e.target.value;save()};document.querySelectorAll('[name=choice]').forEach(e=>e.onchange=()=>{d.choice=+e.value;save()});if(!d.revealed){document.getElementById('reveal').onclick=()=>{if(!d.answer.trim()||d.choice===null){document.getElementById('validation').textContent='请先写下自己的解释，并选择一个判断；不确定也可以如实写出来。';return}d.revealed=true;save();exercise()}}else{document.querySelectorAll('[data-check]').forEach(e=>e.onchange=()=>{d.checks[+e.dataset.check]=e.checked;save()});document.querySelectorAll('[name=transfer]').forEach(e=>e.onchange=()=>{d.transfer=+e.value;save()});document.getElementById('note').oninput=e=>{d.note=e.target.value;save()};document.getElementById('finish').onclick=()=>{if(d.transfer===null){document.getElementById('validation').textContent='请先完成新情境判断。';return}const ok=d.choice===t.correct&&d.transfer===t.transferCorrect&&t.rubric.every((_,i)=>d.checks[i]);state.records[t.id]=schedule(state.records[t.id],ok,day());state.history.push({id:t.id,date:day(),answer:d.answer,note:d.note,ok,choice:d.choice,transfer:d.transfer,checks:d.checks.slice()});s.i++;if(s.i>=s.ids.length)state.session=null;save();app.innerHTML=`<div class="card"><span class="tag">${t.id} · 本次反馈</span><h1>${ok?'这次能解释，也能迁移。':'已经找到值得再练的地方。'}</h1><p>${t.explain}</p><p>${ok?'这次判断和要点自查均通过。':'未通过的部分：'+[d.choice!==t.correct?'原情境判断':'',...t.rubric.filter((_,i)=>!d.checks[i]),d.transfer!==t.transferCorrect?'新情境判断':''].filter(Boolean).map(esc).join('；')}</p><p>下次复习：<strong>${state.records[t.id].due}</strong>。${ok?'隔一段时间再凭记忆解释。':'下次先回忆这些要点，再看课件。'}</p><p>${storageOK?'本次记录已保存。':'保存失败，请返回首页导出备份。'}</p><button class="primary" id="next">${state.session?'继续下一个主题':'完成本轮，回到首页'}</button></div>`;document.getElementById('next').onclick=()=>state.session?exercise():home()}}}
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importFile(e){const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const s=JSON.parse(await f.text());if(!valid(s))throw Error();if(!confirm('导入会替换当前学习记录。建议先导出当前记录。继续吗？'))return;state=s;loadError=false;save();home();notice.textContent=storageOK?'备份已导入并保存':'备份已载入，但无法保存，请在关闭前导出。'}catch(err){document.getElementById('import-status').textContent='未导入：文件不是兼容的学习记录，当前进度未改变。'}}
home();if(loadError)save();
}

