const assert=require('node:assert/strict');
const fs=require('node:fs');const vm=require('node:vm');
const core=require('./app.js');
assert.equal(core.plus('2026-12-31',1),'2027-01-01');
assert.equal(core.schedule(null,false,'2026-10-17').due,'2026-10-18');
let r;for(const n of [1,3,7,14,14]){r=core.schedule(r,true,'2026-10-17');assert.equal(r.due,core.plus('2026-10-17',n))}
assert.equal(core.schedule(r,false,'2026-10-17').streak,0);
assert(core.valid(core.fresh()));assert(!core.valid({version:1}));
let stored=null;
function boot(){
 const elements=new Map();let html='';let nodes=[];
 const el=id=>{if(!elements.has(id))elements.set(id,{textContent:'',className:'',value:'',click(){this.onclick?.()}});return elements.get(id)};
 Object.defineProperty(el('app'),'innerHTML',{set(v){html=v;nodes=[];for(const m of v.matchAll(/<input\b([^>]+)>/g)){const a=m[1];nodes.push({name:a.match(/name="([^"]+)"/)?.[1],value:a.match(/value="([^"]+)"/)?.[1],dataset:{check:a.match(/data-check="([^"]+)"/)?.[1]},checked:/\schecked/.test(a)})}},get(){return html}});
 const context={document:{getElementById:el,querySelectorAll:q=>q==='[data-check]'?nodes.filter(n=>n.dataset.check!==undefined):nodes.filter(n=>n.name===q.match(/name=(\w+)/)?.[1]),createElement:()=>({click(){}})},localStorage:{getItem:()=>stored,setItem:(k,v)=>stored=v},Date,console,setTimeout,Blob,URL,confirm:()=>true};
 vm.runInNewContext(fs.readFileSync('app.js','utf8'),context);
 return {el,html:()=>html,nodes:()=>nodes,select(name,value){const n=nodes.find(n=>n.name===name&&+n.value===value);assert(n);n.onchange()},write(id,value){el(id).oninput({target:{value}})}};
}
let b=boot();b.el('start').click();b.el('reveal').click();assert.match(b.el('validation').textContent,/请先/);
b.write('answer','我还以为买域名就可以。');b.select('choice',0);
b=boot();assert.match(b.html(),/继续复习/);b.el('start').click();assert.match(b.html(),/我还以为买域名/);
b.el('reveal').click();assert.match(b.html(),/需要修正/);b.select('transfer',1);b.el('finish').click();assert.match(b.html(),/值得再练/);
let state=JSON.parse(stored);assert.equal(state.history.length,1);assert.equal(state.records.W1.weak,true);assert.equal(state.records.W1.due,core.plus(core.day(),1));assert.equal(state.session.i,1);
b.el('next').click();b.write('answer','浏览器本地保存不能证明共享，需要共同状态来源、独立客户端和重启检查。');b.select('choice',2);b.el('reveal').click();for(const n of b.nodes().filter(n=>n.dataset.check!==undefined)){n.checked=true;n.onchange()}b.select('transfer',0);b.write('note','明天试着重新解释两个检查');b.el('finish').click();state=JSON.parse(stored);assert.equal(state.records.W2.weak,false);assert.equal(state.history[1].note,'明天试着重新解释两个检查');
b.el('next').click();b.write('answer','服务端逐次检查身份和归属，拒绝成员越权，保留管理员访问，不暴露凭据。');b.select('choice',0);b.el('reveal').click();for(const n of b.nodes().filter(n=>n.dataset.check!==undefined)){n.checked=true;n.onchange()}b.select('transfer',1);b.el('finish').click();state=JSON.parse(stored);assert.equal(state.session,null);assert.equal(state.history.length,3);assert(core.valid(state));b.el('next').click();assert.match(b.html(),/今天的到期主题已完成/);
b=boot();assert.match(b.html(),/需要再练/);assert.match(b.html(),/明天试着重新解释/);
